package com.hotel.service;
import com.hotel.dao.UserDao; import com.hotel.dto.SessionUser; import com.hotel.model.User; import org.mindrot.jbcrypt.BCrypt; import java.util.Locale;
public class AuthService { private final UserDao users; public AuthService(UserDao users){this.users=users;} public SessionUser authenticate(String email,String password){String normalized=email==null?"":email.trim().toLowerCase(Locale.ROOT);if(normalized.isBlank()||password==null)return null;User u=users.findByEmail(normalized).orElse(null);if(u==null||!"ACTIVE".equals(u.getStatusCode())||u.getPasswordHash()==null)return null;try{if(!BCrypt.checkpw(password,u.getPasswordHash()))return null;}catch(IllegalArgumentException invalidHash){return null;}return new SessionUser(u.getUserId(),u.getEmail(),u.getFullName(),u.getRoleCode());} }
